begin;
set local search_path=public,extensions;
select no_plan();
select ok(not exists(select 1 from public.signature_provider_configs where provider_code='YOUSIGN'),'installing transport does not provision an approved provider or legal policy');
select ok((select not public and file_size_limit=20971520 and allowed_mime_types=array['application/pdf','application/json'] from storage.buckets where id='signature-provider-evidence'),'native evidence bucket is private and restricts size and MIME');
select ok(exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='signature_provider_evidence_private_only' and permissive='RESTRICTIVE'),'broad Storage grants cannot expose native signature artifacts to browser roles');
select ok((select count(*)=7 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'yousign_%' and c.relkind='r'),'all seven native transport tables have RLS');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'yousign_%' and c.relkind='r' and (has_table_privilege('authenticated',c.oid,'SELECT') or has_table_privilege('authenticated',c.oid,'INSERT') or has_table_privilege('service_role',c.oid,'UPDATE'))),'tenant users and workers cannot bypass the transport command API');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_signature_dispatch_provider_v1','get_yousign_envelope_v1','begin_yousign_dispatch_v1','record_yousign_reference_v1','finish_yousign_dispatch_v1','record_yousign_native_artifact_v1','record_yousign_verified_event_v1') and has_function_privilege('authenticated',p.oid,'EXECUTE')),'tenant role cannot impersonate a worker or a verified webhook');
select ok((select count(*)=7 and bool_and(has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_signature_dispatch_provider_v1','get_yousign_envelope_v1','begin_yousign_dispatch_v1','record_yousign_reference_v1','finish_yousign_dispatch_v1','record_yousign_native_artifact_v1','record_yousign_verified_event_v1')),'only worker role has the native transport commands');
select ok(not has_function_privilege('anon','public.configure_yousign_signer_v1(uuid,text,text,text,jsonb)','EXECUTE') and has_function_privilege('authenticated','public.configure_yousign_signer_v1(uuid,text,text,text,jsonb)','EXECUTE'),'signer preparation is an authenticated human operation');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"018bbbbb-2222-4333-8444-555555555555"}',true);
select throws_ok($$select public.get_signature_dispatch_provider_v1('018bbbbb-2222-4333-8444-555555555555')$$,'42501','SIGNATURE_DISPATCH_DENIED','provider lookup independently checks the JWT service role');
select throws_ok($$select public.begin_yousign_dispatch_v1('018bbbbb-2222-4333-8444-555555555555','SEND','test-operation-key')$$,'42501','YOUSIGN_SERVICE_REQUIRED','forged JWT cannot claim native sends');
select throws_ok($$select public.record_yousign_reference_v1('018bbbbb-2222-4333-8444-555555555555','REQUEST','018bbbbb-2222-4333-8444-555555555556')$$,'42501','YOUSIGN_SERVICE_REQUIRED','forged JWT cannot bind provider IDs');
select throws_ok($$select public.finish_yousign_dispatch_v1('018bbbbb-2222-4333-8444-555555555555','SEND','test-operation-key','ACCEPTED')$$,'42501','YOUSIGN_SERVICE_REQUIRED','forged JWT cannot acknowledge a provider write');
select throws_ok($$select public.record_yousign_verified_event_v1('018bbbbb-2222-4333-8444-555555555555','{}')$$,'42501','YOUSIGN_SERVICE_REQUIRED','forged JWT cannot attest an external signature event');
select throws_ok($$select public.configure_yousign_signer_v1('018bbbbb-2222-4333-8444-555555555555','Mina','Alami','fr','[]')$$,'42501','YOUSIGN_SIGNER_CONFIGURATION_DENIED','unknown or foreign signer cannot be configured');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.begin_yousign_dispatch_v1('018bbbbb-2222-4333-8444-555555555555','SEND','test-operation-key')$$,'55000','YOUSIGN_SANDBOX_POLICY_REQUIRED','service role cannot turn a missing governed envelope into a remote signature');
select throws_ok($$select public.finish_yousign_dispatch_v1('018bbbbb-2222-4333-8444-555555555555','SEND','test-operation-key','ACCEPTED')$$,'55000','YOUSIGN_OPERATION_NOT_CLAIMED','an unclaimed remote operation cannot be acknowledged');
select throws_ok($$select public.finish_yousign_dispatch_v1('018bbbbb-2222-4333-8444-555555555555','SEND','test-operation-key','SIGNED')$$,'22023','YOUSIGN_OUTCOME_INVALID','transport acceptance cannot be promoted to a signed legal result');
select throws_ok($$select public.get_yousign_envelope_v1(null,null)$$,'22023','YOUSIGN_EXACT_REFERENCE_REQUIRED','lookup requires exactly one local or remote identifier');
select throws_ok($$select public.get_yousign_envelope_v1('018bbbbb-2222-4333-8444-555555555555','018bbbbb-2222-4333-8444-555555555556')$$,'22023','YOUSIGN_EXACT_REFERENCE_REQUIRED','ambiguous local and provider lookups are denied');
select is((select count(*)::integer from private.yousign_requests_v1),0,'denied operations create no native provider reference');
select is((select count(*)::integer from private.yousign_dispatch_operations_v1),0,'denied operations create no durable operation claim');
select * from finish();
rollback;
